(window.__quranSurahs=window.__quranSurahs||{})[112]={"nomPhon":"Al-Ikhlaas","versets":{"1":{"text":"Dis: «Il est Allah, Unique.","arabe":"قُلْ هُوَ ٱللَّهُ أَحَدٌ"},"2":{"text":"Allah, Le Seul à être imploré pour ce que nous désirons.","arabe":"ٱللَّهُ ٱلصَّمَدُ"},"3":{"text":"Il n'a jamais engendré, n'a pas été engendré non plus.","arabe":"لَمْ يَلِدْ وَلَمْ يُولَدْ"},"4":{"text":"Et nul n'est égal à Lui».","arabe":"وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ"}}};